INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Machine Learning Basics: A Comprehensive Guide.  A Review', 'Alok Singh Chauhan; H Mary Henrietta', 2023, '<jats:p>The domain of machine learning has experienced an unparalleled increase in attention and implementation, becoming an essential component of diverse businesses. This review paper provides a thorough analysis of the comprehensive handbook named "Machine Learning Basics: A Comprehensive Guide." Written by [Dr. Jane Doe], this guide has become a vital reference for those at all levels of expertise seeking to comprehend and traverse the intricate realm of machine learning.</jats:p>', '10.58496/bjml/2023/006', 'https://doi.org/10.58496/bjml/2023/006' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.58496/bjml/2023/006');
