INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Deep Chinese Teaching and Learning Model Based on Deep Learning', 'Yipu Wang; Stuart Perrin', 2024, '<jats:p>Deep learning is a more situational and reflective way of learning that integrates complex knowledge and skills into intuitive thinking. As a language that closely combines sound, form and meaning, Chinese teaching and learning from the perspective of deep learning can help break through the limitations of the current teaching model that only focuses on certain language knowledge or cultural behaviors. This paper combines deep learning with international Chinese education, creates deep Chinese teaching and learning model including “four stages and ten steps”, and carries out practical application and teaching effect test. The results show that the deep Chinese teaching and learning model is conducive to improving students’ discourse presentation ability and comprehensive skills, cultivating the learners’ autonomous learning ability and intercultural communication competence, and strengthening the integration of language teaching and cultural teaching. At the same time, this model also has some limitations, need to be further adjusted and optimized.</jats:p>', '10.18178/ijlll.2024.10.1.479', 'https://doi.org/10.18178/ijlll.2024.10.1.479' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.18178/ijlll.2024.10.1.479');
