INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Improving Student Learning Outcomes in Fiqh Learning through the Student Problem Based Learning Model at MI Nurul Jihad', 'Muzanni; Najla', 2025, '<jats:p>This study aims to improve the learning motivation of fifth grade students of MI Nurul Jihad in the subject of Fiqh through the application of the Problem Based Learning learning model. The background of the study identified that the learning process tends to focus on memorization, does not involve students actively, and results in low learning motivation. This condition is influenced by limited facilities and infrastructure, lack of mastery of science and technology by teachers, and low student interest in learning. Based on these problems, this classroom action research was formulated to answer the question: "Can the use of the Problem Based Learning learning model improve students'' learning motivation in the field of Fiqh studies of fifth grade MI Nurul Jihad?" This study uses the Classroom Action Research method that focuses on the implementation of the Problem Based Learning model. Data were collected through tests, observations, and documentation, then analyzed descriptively qualitatively. The results of initial observations showed low student participation and learning outcomes, where only 66.7% of students (10 out of 15) achieved completion with an average score of 65.33. After implementing cycle I of the PBL model, there was a significant increase in student learning outcomes, with 80.0% of students (12 out of 15) achieving completion and the class average score increasing to 75.0.</jats:p>', '10.62945/deeplearning.v1i1.211', 'https://doi.org/10.62945/deeplearning.v1i1.211' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.62945/deeplearning.v1i1.211');
INSERT INTO tags (name) SELECT 'Deep Learning' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Deep Learning');
INSERT INTO publications_tags (publication_id, tag_id) SELECT p.id, t.id FROM publications p JOIN tags t ON t.name = 'Deep Learning' WHERE p.doi = '10.62945/deeplearning.v1i1.211' AND NOT EXISTS (SELECT 1 FROM publications_tags pt WHERE pt.publication_id = p.id AND pt.tag_id = t.id);
INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Learning Innovation in Global Citizenship Education by Integrating Deep Learning Approach', 'Sutrisno Sutrisno; Sunarto Sunarto; Dyah Mustikasari', 2025, '<jats:p>Conventional learning methods in dealing with the complexity of dynamic and multidimensional global issues in learning global citizenship education are still ineffective, this can be seen from the low understanding and awareness of students in solving global issues that occur. This research aims to develop and test learning innovations by integrating deep learning approaches to improve students'' understanding and participation in the context of global citizenship. The research method used was quantitative research with an experimental approach. The research subjects consisted of senior high school students in a sample school. The research instruments included questionnaires, comprehension tests, and observations used to measure the effectiveness of learning before and after the application of the deep learning approach. The collected data were analyzed using descriptive and inferential statistics to assess the improvement of learning outcomes. The results showed that the integration of deep learning approach in global citizenship education significantly improved students'' concept understanding, critical thinking skills, and learning motivation. Students become more active and able to connect civic education materials with contemporary global issues more deeply. The implication of this research finding is that the application of deep learning technology can be an effective innovative strategy in developing global citizenship education that is adaptive and responsive to the challenges of the times. This encourages educators to utilize artificial intelligence technology in the learning process to create a more interactive and meaningful learning experience.</jats:p>', '10.23917/jdl.v1i2.11224', 'https://doi.org/10.23917/jdl.v1i2.11224' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.23917/jdl.v1i2.11224');
INSERT INTO tags (name) SELECT 'Deep Learning' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Deep Learning');
INSERT INTO publications_tags (publication_id, tag_id) SELECT p.id, t.id FROM publications p JOIN tags t ON t.name = 'Deep Learning' WHERE p.doi = '10.23917/jdl.v1i2.11224' AND NOT EXISTS (SELECT 1 FROM publications_tags pt WHERE pt.publication_id = p.id AND pt.tag_id = t.id);
INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Deep Reinforcement Learning: An Innovative Approach that Combines Deep Learning and Reinforcement Learning', 'Yan Cui', 2026, '<jats:p>Deep reinforcement learning (DRL) has emerged as a transformative paradigm that integrates the powerful representation-learning capabilities of deep neural networks with the sequential decision-making framework of reinforcement learning. Building upon the foundations of value functions, policy optimization, and Markov decision processes, DRL enables agents to operate effectively in high-dimensional, nonlinear, and dynamic environments where traditional methods fall short. This article provides a comprehensive overview of the theoretical principles, core algorithms, and key enabling techniques—such as neural network architectures, experience replay, Deep Q-Networks, and policy-gradient approaches—that underpin modern DRL systems. In addition, the paper examines several prominent application domains, including gaming, robotics, autonomous driving, finance, and healthcare, highlighting how DRL facilitates adaptive control, long-term optimization, and human-centered interaction. Challenges such as sample inefficiency, limited interpretability, and safety concerns are discussed, alongside emerging directions including model-based RL, multimodal learning, transfer learning, and ethical considerations. Overall, this study underscores the substantial potential of deep reinforcement learning to advance artificial intelligence and provides insights into future research necessary to ensure reliable, efficient, and responsible deployment of DRL technologies.</jats:p>', '10.56028/aetr.16.1.500.2026', 'https://doi.org/10.56028/aetr.16.1.500.2026' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.56028/aetr.16.1.500.2026');
