INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Down the deep rabbit hole: Untangling deep learning from machine learning and artificial intelligence', 'Niel Chah', 2019, '<jats:p>Interest in deep learning, machine learning, and artificial intelligence from industry and the general public has reached a fever pitch recently. However, these terms are frequently misused, confused, and conflated. This paper serves as a non-technical guide for those interested in a high-level understanding of these increasingly influential notions by exploring briefly the historical context of deep learning, its public presence, and growing concerns over the limitations of these techniques. As a first step, artificial intelligence and machine learning are defined. Next, an overview of the historical background of deep learning reveals its wide scope and deep roots. A case study of a major deep learning implementation is presented in order to analyze public perceptions shaped by companies focused on technology. Finally, a review of deep learning limitations illustrates systemic vulnerabilities and a growing sense of concern over these systems.</jats:p>', '10.5210/fm.v24i2.8237', 'https://doi.org/10.5210/fm.v24i2.8237' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.5210/fm.v24i2.8237');
