INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Deep Learning-Based Learning Strategies in Realizing Meaningful, Critical, and Enjoyable Learning', 'Rizwatul Hasanah; Harun Joko Prayitno; Suni Tuti; Sarilan Sarilan; Velandani Prakoso', 2025, '<jats:p>This study aims to examine the form and scope of the application of Deep Learning in the Vocational High School (SMK), especially at SMK Mantingan, through a literature study approach. Deep Learning, as part of artificial intelligence, has great potential in the world of vocational education, especially in supporting technology-based learning and improving student competencies in the digital field. This study relies on various literature sources such as scientific journals, books, articles, and relevant documents to examine the concepts, applications, and challenges faced in the integration  of Deep Learning in vocational schools. The results of the study show that although the application  of Deep Learning in vocational schools, including at SMK Mantingan, is still relatively new and limited, there are great opportunities for development in project-based learning and improving students'' digital literacy. The scope of implementation includes the introduction of basic concepts, the use of supporting software, and the use of simple models for educational purposes. This study recommends the need for teacher training, the provision of adequate infrastructure, and collaboration with higher education institutions or industry to expand the application of this technology in vocational schools.</jats:p>', '10.23917/jdl.v1i2.11572', 'https://doi.org/10.23917/jdl.v1i2.11572' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.23917/jdl.v1i2.11572');
