INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Deep Learning vs Differentiated Learning: Learning Innovation in Islamic Boarding School-Based Middle Schools', 'Murwanto Setyo Nugroho; Harun Joko Prayitno; Koesoemo Ratih; Muhammad Samsudin', 2025, '<jats:p>This study aims to examine the implementation of deep learning and differentiated learning approaches in Islamic boarding school-based junior high schools (SMP) in order to improve the quality of meaningful, contextual, and humanistic learning. Using a descriptive qualitative approach, data were collected through in-depth interviews, classroom observations, and documentation studies in three Islamic boarding school junior high schools that integrate national and religious curricula. The results of the study indicate that learning strategies such as project-based learning, reflective discussions, and collaborative activities are effective in building conceptual understanding and spiritual values ​​of students. Differentiated learning enables the creation of an inclusive learning environment by adjusting content, processes, and products according to students'' learning profiles. Implementation challenges arise in terms of time constraints, dual curriculum burdens, and teacher professional readiness. Authentic project-based and portfolio-based evaluations are more relevant in measuring cognitive, affective, and spiritual competencies holistically. This study recommends the need for educational policies that are more adaptive to the characteristics of Islamic boarding schools, including contextual teacher training, curriculum flexibility, and an inclusive and sustainable evaluation system. These findings confirm that deep learning and differentiated learning have great potential in transforming Islamic boarding school education towards 21st-century learning that is more humanistic, reflective, and transformative.</jats:p>', '10.23917/jdl.v1i1.11246', 'https://doi.org/10.23917/jdl.v1i1.11246' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.23917/jdl.v1i1.11246');
