INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Questionable Practices in Methodological Deep Learning Research', 'Daniel J. Trosten', 2023, '<jats:p>Evaluation of new methodology in deep learning (DL) research is typically done by reporting point estimates of a few performance metrics, calculated from a single training run. This paper argues that this frequently used evaluation protocol in DL is fundamentally flawed -- presenting 8 questionable practices that are widely adopted in the evaluation of new DL methods. The questionable practices are derived from violations of statistical principles of the scientific method, and from Hansson''s definition of pseudoscience. A survey of recent publications from a top-tier DL conference indicates the widespread adoption of these practices in state-of-the-art DL research. Lastly, arguments in favor of the questionable practices, possible reasons for their adoption, and measures that have been taken to remove them, are discussed.</jats:p>', '10.7557/18.6804', 'https://doi.org/10.7557/18.6804' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.7557/18.6804');
