INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'RIDDLE: Rule Induction with Deep Learning', 'Cosimo Persia; Ricardo Guimarães', 2023, '<jats:p>Numerous applications rely on the efficiency of Deep Learning models to address complex classification tasks for critical decisions-making. However, we may not know how each feature in these models contributes towards the prediction. In contrast, Rule Induction algorithms provide an interpretable way to extract patterns from data, but traditional approaches suffer in terms of scalability. In this work, we bridge Deep Learning and Rule Induction and define the RIDDLE (Rule Induction with Deep Learning) architecture. We show that RIDDLE has state-of-the-art performance in Rule Induction via an empirical evaluation.</jats:p>', '10.7557/18.6801', 'https://doi.org/10.7557/18.6801' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.7557/18.6801');
