INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Improving Understanding and Attitude of Gratitude Using Project Based Learning Model in Islamic Education Learning at SMP Negeri 1 Barumun Baru', 'Hayatunnisah Nst', 2025, '<jats:p>This study aims to improve student learning outcomes in Islamic religious education learning using Project Based Learning. This study is a classroom action research that uses four steps, namely planning, action, observation and reflection. The subjects of this study were junior high school students. The data for this study were obtained using test and observation techniques. Tests are used to measure learning outcomes and observations are used to analyze teacher and student learning activities. The data analysis technique used in this study is descriptive statistics by comparing the results obtained with indicators of research success. The results of the study indicate that Project Based Learning can improve student learning outcomes in Islamic religious education learning. This can be seen from the increase in the percentage of student learning completion in each cycle with details of the pre-cycle 48.71%, the first cycle 65.39% and in the second cycle it increased to 89.76%. Thus, the use of Project Based Learning can be used as an alternative to improve student learning outcomes in Islamic religious education learning.</jats:p>', '10.62945/deeplearning.v1i1.205', 'https://doi.org/10.62945/deeplearning.v1i1.205' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.62945/deeplearning.v1i1.205');
