INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Spectral Deep Learning in Chronic Pulmonary Thromboembolism', 'Henrique J Cirino', 2024, '<jats:p>Pulmonary scintigraphy is considered a technique of choice in the evaluation of chronic pulmonary thromboembolism. Technical advancements in computed tomography as dual-energy (spectral) have allowed obtaining high quality images. As an example, a computed tomography as dual-energy patient case is shown, who underwent both scintigraphy and spectral deep learning not only was a lower radiation dose observed scintigraphy but also provided anatomical data on perfusion defect, essential for surgical planning and also evidenced other areas of perfusion alteration that were not clearly identified on V/Q scintigraphy. Thus, we bring this initial experience with the use of Spectral Deep Learning as a possibility to combine anatomical and perfusional assessment in the same acquisition, reducing dose and possible costs</jats:p>', '10.53902/atr.2024.02.000502', 'https://doi.org/10.53902/atr.2024.02.000502' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.53902/atr.2024.02.000502');
