INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Penerapan Problem Based Learning Terintegrasi Deep Learning untuk Meningkatkan Motivasi Belajar Siswa', 'Rifninda Nur Linasari; Ana Fitrotun Nisa', 2025, '<jats:p>Penelitian ini bertujuan untuk menganalisis peningkatan motivasi belajar IPAS siswa kelas V di SD Negeri Jetisjogopaten Tahun Ajaran 2024/2025 setelah diterapkannya model pembelajaran Problem Based Learning terintegrasi pendekatan Deep Learning. Jenis penelitian ini adalah Penelitian Tindakan Kelas (PTK) dengan subjek penelitian adalah siswa kelas V yang berjumlah 20 orang siswa. Data motivasi belajar IPAS siswa dikumpulkan melalui angket. Data yang diperoleh dianalisis menggunakan analisis statistik deskriptif. Berdasarkan hasil analisis data, pada siklus I rerata motivasi belajar IPAS siswa kelas V di SD Negeri Jetisjogopaten setelah mengikuti pembelajaran dengan menerapkan model pembelajaran Problem Based Learning terintegrasi Deep Learning sebesar 77,82 dan berada pada kategori sedang. Persentase ketuntasan klasikalnya adalah 72,46%. Pada siklus II rerata motivasi belajar IPAS siswa kelas V di SD Negeri Jetisjogopaten setelah mengikuti pembelajaran dengan menerapkan model pembelajaran Problem Based Learning meningkat yakni menjadi 83,45 dan berada pada kategori tinggi. Persentase ketuntasan klasikalnya adalah 87,64%. Berdasarkan hasil tersebut dapat disimpulkan bahwa model pembelajaran Problem Based Learning terintegrasi pendekatan Deep Learning secara efektif mampu meningkatkan motivasi belajar IPAS siswa.</jats:p>', '10.23887/jpp.v58i3.95456', 'https://doi.org/10.23887/jpp.v58i3.95456' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.23887/jpp.v58i3.95456');
