INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'COMBINAÇÃO DE DEEP LEARNING E MACHINE LEARNING PARA DIAGNÓSTICO AUXILIADO POR INTELIGÊNCIA ARTIFICIAL', 'Fábio Lofredo Cesar; Hygor Santiago Lara', 2025, '<jats:p>Este trabalho propõe um sistema híbrido que combina a ResNet (Residual Network - amplamente reconhecida por seu impacto no aprendizado profundo, sendo um marco na área de visão computacional) com Árvores Extremamente Aleatórias (Extra Trees) para classificar imagens de raio-X de tórax e auxiliar na detecção de doenças. A abordagem utiliza a técnica de Transfer Learning, onde a ResNet, previamente treinada, é empregada para extrair características relevantes das imagens. Em seguida, o algoritmo Extra Trees realiza a classificação com base nessas características. Na etapa inicial, utilizando apenas a ResNet combinada com uma pequena rede neural, obtivemos uma acurácia de 95,40% na validação e 79,33% nos testes. Com a implementação do sistema híbrido, os resultados foram significativamente aprimorados, alcançando 96,90% de acurácia na validação e 89,98% nos testes, representando uma melhoria expressiva de aproximadamente 10 pontos percentuais nos testes. Esses resultados destacam o potencial do sistema híbrido em aplicações, demonstrando como a combinação de técnicas avançadas de aprendizado profundo e aprendizado de máquina pode contribuir significativamente para a melhoria da precisão.</jats:p>', '10.56238/arev7n3-111', 'https://doi.org/10.56238/arev7n3-111' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.56238/arev7n3-111');
