INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Deep Learning: Implementation and Impact in Islamic Junior High  Schools', 'Erda Farid Hidayani; Harun Joko Prayitno; Trisakti Handayani', 2025, '<jats:p>This study aims to describe the implementation of deep learning strategies at the secondary level within an Islamic educational setting, specifically at SMP Islam Ar‑Rahmah. A descriptive qualitative approach was employed to examine in depth the teaching–learning processes integrated with Islamic values and the school’s sociocultural context. Data were gathered through participatory observation, in‑depth interviews, and the documentation of instructional materials. The findings reveal that deep learning was effectively realized through Problem‑Based Learning (PBL) and Project‑Based Learning (PjBL) in both the natural science (IPA) and social science (IPS) curricula. Students actively engaged in contextualized projects—such as the Socio Project Board initiative and water‑filtration experiments—which fostered critical thinking, collaborative teamwork, and data‑driven decision‑making competencies. Moreover, the integration of religious programming and boarding‑school activities contributed to the development of intrapersonal and interpersonal skills that align with the core values of Pancasila students. Nevertheless, challenges persist, particularly with respect to instructional design and the availability of teacher training. Consequently, systemic support from educational institutions and policymakers is necessary to bolster the sustainable and meaningful implementation of deep learning in Islamic schools.</jats:p>', '10.23917/jdl.v1i1.11077', 'https://doi.org/10.23917/jdl.v1i1.11077' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.23917/jdl.v1i1.11077');
