INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Deep Transfer Learning in der Arbeitsplanung/Deep transfer learning in process planning – A concept for applying deep transfer learning in process planning using the example of manufacturing operations selection', 'Marco Hussong; Moritz Glatt; Jan C. Aurich', 2023, '<p>Für die Nutzung von Deep Learning zur Unterstützung der Prozesse innerhalb der Arbeitsplanung wird eine Vielzahl von Daten benötigt. In der industriellen Praxis ist die Aufbereitung solcher Datensätze sehr komplex und mit hohen Aufwand verbunden. Durch die Nutzung von Deep Transfer Learning kann die benötigte Datenmenge reduziert werden. Am Beispiel der Fertigungsvorgangsermittlung wird ein Konzept vorgestellt, das die Anwendung von Deep Transfer Learning innerhalb der Arbeitsplanung ermöglicht. </p>           <p> </p>           <p>A large amount of data is required for the use of deep learning to support process planning. In industrial practice, the preparation of such data sets is very complex and requires a lot of manual effort. By using deep transfer learning, the required amount of data can be reduced. Therefore, using the example of manufacturing operation selection, a concept is introduced that enables the application of deep transfer learning within process planning.</p>', '10.37544/1436-4980-2023-06-16', 'https://doi.org/10.37544/1436-4980-2023-06-16' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.37544/1436-4980-2023-06-16');
INSERT INTO tags (name) SELECT 'Deep Learning' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Deep Learning');
INSERT INTO publications_tags (publication_id, tag_id) SELECT p.id, t.id FROM publications p JOIN tags t ON t.name = 'Deep Learning' WHERE p.doi = '10.37544/1436-4980-2023-06-16' AND NOT EXISTS (SELECT 1 FROM publications_tags pt WHERE pt.publication_id = p.id AND pt.tag_id = t.id);
INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Seafloor Pipeline Detection With Deep Learning', 'Vemund Sigmundson Schøyen; Narada Dilp Warakagoda; Øivind Midtgaard', 2021, '<jats:p>This paper presents fast, accurate, and automatic methods for detecting seafloor pipelines in multibeam echo sounder data with deep learning. The proposed methods take inspiration from the highly successful ResNet and YOLO deep learning models and tailor them to the idiosyncrasies of the seafloor pipeline detection task.&#x0D; We use the area between lines and Hausdorff line distance functions to accurately evaluate how well methods can localize (pipe)lines. The same functions also show promise as loss functions compared to standard mean squared error, which does not include the regression variables'' geometrical interpretation.&#x0D; The model outperforms the highest likelihood baseline by more than 35% on a region-wise F1-score classification evaluation while being more than eight times more accurate than the baseline in locating pipelines. It is efficient, operating at over eighteen 32-ping image segments per second, which is far beyond real-time requirements.</jats:p>', '10.7557/18.5699', 'https://doi.org/10.7557/18.5699' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.7557/18.5699');
INSERT INTO tags (name) SELECT 'Deep Learning' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Deep Learning');
