INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Pricing cloud IaaS computing services', 'Nicola Dimitri', 2020, '<jats:title>Abstract</jats:title><jats:p>The economics of cloud computing has recently attracted increasing attention. In particular, a topic which is still under debate is how prices charged to customers for cloud resources are formed, since alternative pricing rules could be considered. Based on three pricing schemes inspired by those used by Amazon EC2, the main global cloud service provider, in the paper we address two main issues. First we present a methodology for the relevant parameters of the pricing rules to be determined in an optimal way, that is to maximise the provider’s revenue. Moreover, we discuss reasons for co-existence of three pricing rules, rather than fewer, to access the cloud. Our findings suggest that this may be due to a larger coverage of the potential demand, since customers applying for cloud services vary in their willingness to pay for the job, the time length of the service, the computational power requested etc. Furthermore, the pricing rule in the so-called, spot market, can provide the platform with useful information on the customers willingness to pay for cloud services. This is because in the spot market users offer a price for service, but pay less than that if their request is satisfied.</jats:p>', '10.1186/s13677-020-00161-2', 'https://doi.org/10.1186/s13677-020-00161-2' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1186/s13677-020-00161-2');
INSERT INTO tags (name) SELECT 'Cloud Computing' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Cloud Computing');
INSERT INTO publications_tags (publication_id, tag_id) SELECT p.id, t.id FROM publications p JOIN tags t ON t.name = 'Cloud Computing' WHERE p.doi = '10.1186/s13677-020-00161-2' AND NOT EXISTS (SELECT 1 FROM publications_tags pt WHERE pt.publication_id = p.id AND pt.tag_id = t.id);
