INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Data Mining как фундаментальная область современного анализа данных', 'А.О. Токсубаева', 2019, '<jats:p>В предложенной статье рассматривается интеллектуальный анализ данных, методы и задачи Data Mining рассказана история появления Data Mining описана суть и цель Data Mining рассмотрены основные определения поиска ассоциативных правил, такие как: транзакция, транзакционная база данных, поддержка, достоверность, подъем и приведены формулы их вычисления сформулирована постановка задачи поиска ассоциативного правила выявлена сущность свойства антимонотонности описаны сферы жизнедеятельности, где применяются ассоциативные правила и цели их использования доказано утверждение, что Data Mining является фундаментальной областью современного анализа данных.</jats:p>', '10.34755/irok.2019.5.5.179', 'https://doi.org/10.34755/irok.2019.5.5.179' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.34755/irok.2019.5.5.179');
