INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Model-Driven Engineering for Software Product Lines', 'Jean-Marc Jézéquel', 2012, '<jats:p>Modeling variability in the context of software product-lines has been around for about 25 years in the research community. It started with Feature Modeling and soon enough was extended to handle many different concerns. Beyond being used for a mere description and documentation of variability, variability models are more and more leveraged to produce other artifacts, such as configurators, code, or test cases. This paper overviews several classification dimensions of variability modeling and explores how do they fit with such artifact production purposes.</jats:p>', '10.5402/2012/670803', 'https://doi.org/10.5402/2012/670803' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.5402/2012/670803');
