INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'CYBERSECURITY MANAGEMENT OF IT PRODUCTS', 'Ihor Frolov; Yanina Kolodinska', 2024, '<jats:p>The article delves into the pressing issues of cybersecurity management for IT products. Particular attention is paid to the types of cyber threats and methods for enhancing the security of enterprises and IT products. The importance of researching this topic in the context of the development of the IT industry in Ukraine and the role of the IT sphere for the domestic economy in the conditions of full-scale russian aggression is emphasized. Modern trends of malicious use of information technologies in hybrid warfare are analyzed, which necessitates the study of tools for committing cybercrimes, key groups of attackers, and information that is a constant target for cyberattacks. The paper analyzes modern methods of cyberattacks and their consequences on the quality of the IT product and the activities of the enterprise. Based on the obtained results, recommendations for the formation of an effective cybersecurity system are developed. In particular, the key directions of cybersecurity for the enterprise are defined, aimed at strengthening protection and increasing the competitiveness of domestic IT product developers in the international and domestic markets. The relevance of the research topic in the context of the redistribution of budget funds to critically important sectors of the economy is emphasized, which requires the management of IT product manufacturers to search for domestic and international investments. In this context, ensuring reliable methods and tools of cybersecurity is considered as one of the key factors of competitiveness of modern IT product developers. Overall, the article presents a comprehensive approach to the study of cybersecurity management of IT products, which is especially relevant in the conditions of hybrid warfare and the growing dependence of the economy on the IT sphere. The results obtained can be used to create and improve the existing cybersecurity policy for the enterprise and IT products.</jats:p>', '10.28925/2663-4023.2024.23.310317', 'https://doi.org/10.28925/2663-4023.2024.23.310317' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.28925/2663-4023.2024.23.310317');
INSERT INTO tags (name) SELECT 'Cybersecurity' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Cybersecurity');
INSERT INTO publications_tags (publication_id, tag_id) SELECT p.id, t.id FROM publications p JOIN tags t ON t.name = 'Cybersecurity' WHERE p.doi = '10.28925/2663-4023.2024.23.310317' AND NOT EXISTS (SELECT 1 FROM publications_tags pt WHERE pt.publication_id = p.id AND pt.tag_id = t.id);
