INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'CHALLENGES AND RISKS OF GLOBALIZATION IN THE FOCUS OF CYBERSECURITY', 'Heorhii Suskiy', 2025, '<jats:p>The article is devoted to the problems and risks of globalization, which caused the expansion of computer networks. This expansion resembles the process of Westernization in the era of late modernity, when, according to A. Toynbee, the “ubiquitous” Western society held the fate of all humanity in its hands, and is gradually revealing its shortcomings, in particular, in the field of information security. Data theft, insecurity of corporate networks, unauthorized access to information, attempts to exploit vulnerabilities and compromise systems have become one of the most common threats to the cybersecurity of information resources and individual corporations and companies, and states as a whole. In proportion to the development of capabilities and the emergence of new technological solutions that improve the use of networks, the “ingenuity” of cybercriminals is also developing: phishing, sniffing (the process of intercepting and analyzing network traffic using special devices and programs), infection with malicious software, etc. The spectrum and variability of cyber incidents is expanding, the targets of attacks are resources and databases of state institutions, infrastructure facilities, corporate networks. The reverse side of globalization is seen as a system of challenges and risks, which today must be foreseen not only by cybersecurity specialists, but also by digitalization specialists in all state and commercial structures and companies. Computer attackers use increasingly sophisticated methods to penetrate systems and databases, develop tools for infection and distribution of malicious software. There is a need to systematize knowledge and form separate branches to counteract malicious interference in the network and secure databases from cyberattacks.</jats:p>', '10.28925/2663-4023.2025.30.951', 'https://doi.org/10.28925/2663-4023.2025.30.951' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.28925/2663-4023.2025.30.951');
