INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'The Cybersecurity Obligations of States Perceived as Platforms: Are Current European National Cybersecurity Strategies Enough?', 'Vagelis Papakonstantinou', 2022, '<jats:p>Cybersecurity is a relatively recent addition to the list of preoccupations for modern states. The forceful emergence of the internet and computer networks and their subsequent ubiquitusness quickly brought it to the fore. The use of the internet in public and private administrations developed fast from a useful addition to an inherent, embedded element of all relevant policies and strategies. By now modern administrations, regardless whether public or private, are inconceivable outside the digital sphere. Nevertheless, with great opportunities came also great risk. Attacks against computer systems quickly evolved from marginalised incidents to state affairs, and concern. The exponential increase in the importance of cybersecurity over the past few years has led to a multi-level response. New policies, followed by relevant laws and regulations, have been introduced at national and international level. New academic interest has emerged, adding to the traditional studies on security. Perhaps most prominently, however, among these responses, modern states have been compelled to devise concrete cybersecurity strategies. The commonality, however, of computer network technologies and of the internet itself (including the digital means to cause harm) has led to considerable harmonisation among state responses. In other words, national cybersecurity strategies made available over the internet more or less resemble one another. Such uniform thinking could develop into a risk per se: challenges may appear unexpectedly, given also the dynamic nature of the internet and the multitude of actors and sources of risk, that could put common knowledge, if not wisdom, to the test at a stage with limited space for response. This paper builds upon the idea of national states being perceived as platforms within the contemporary digital and regulatory environment. In this context, it elaborates upon a concrete consequence of states-as-platforms within the cybersecurity field. To this end, Section 2 introduces the idea of states as platforms; Section 3 then particularizes this general discussion by specifically referring to the cybersecurity field, in an attempt to highlight specific consequences of states being perceived as platforms. The focus is then turned to the EU, and the NIS Directive’s obligation upon Member States to introduce and implement national cybersecurity strategies, which are therefore examined under the lens introduced in Section 2. Finally, specific points for improvement in these cybersecurity strategies are presented in Section 5.</jats:p>', '10.5604/01.3001.0016.1237', 'https://doi.org/10.5604/01.3001.0016.1237' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.5604/01.3001.0016.1237');
