INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'CYBERSECURITY OF MQTT CONNECTIONS IN AN AUTOMATED GATE CONTROL SYSTEM', 'Oksana Onyshchuk', 2025, '<jats:p>With the development of the Internet of Things (IoT), the issue of data protection and the secure operation of IoT systems has become increasingly important. One of the major threats is unprotected MQTT connections, which are vulnerable to traffic interception (MitM attacks), command spoofing, unauthorized access, and DDoS attacks.This paper explores MQTT security methods using the example of an automated gate control system. It presents an analysis of recent research in IoT cybersecurity, identifies the main vulnerabilities of MQTT brokers and clients, and proposes measures to secure IoT infrastructure.Special attention is given to TLS/SSL encryption for traffic protection, MQTT client authentication, access restrictions using ACL (Access Control List), and the isolation of IoT devices in separate networks (VPN/VLAN).The research findings confirm that a comprehensive implementation of security measures significantly reduces attack risks and ensures the reliable and secure operation of IoT projects.</jats:p>', '10.28925/2663-4023.2025.27.727', 'https://doi.org/10.28925/2663-4023.2025.27.727' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.28925/2663-4023.2025.27.727');
