INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Perspectives on “Good” in Blockchain for Good', 'Glenn Parry; John Collomosse', 2021, '<jats:p>Blockchain projects have been developed to extend the reach of distributed ledger technology (DLT) beyond cryptocurrency to achieve “good” in the world. Such projects may make a claim for moral, ethical, and responsible intent, but many researchers have not critically examined what good means in context. The concept of good has been debated for centuries and whilst we will not conclude the argument, we should engage in the discourse. We propose the idea that exploration across micro, meso, and macro levels of value creating ecosystems is needed. The implications, both practical and theoretical, of the use of blockchain for good require analysis. As the ambition for blockchain innovations to transform society for the better becomes practical reality, understanding of such change will come from transdisciplinary researchers able to bridge knowledge of social and technical systems.</jats:p>', '10.3389/fbloc.2020.609136', 'https://doi.org/10.3389/fbloc.2020.609136' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.3389/fbloc.2020.609136');
