INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Blockchain and financial performance: empirical evidence from major Australian banks', 'Rula Almadadha', 2025, '<jats:p>This study investigates the impact of blockchain technology adoption on the financial performance of major Australian banks, specifically Commonwealth Bank, Westpac, and ANZ, from 2016 to 2023. Using a descriptive research design and secondary data from annual reports, financial performance was assessed through Return on Assets (ROA) and Return on Equity (ROE). The findings indicate a positive relationship between blockchain adoption and improved financial performance, suggesting gains in efficiency, cost management, and profitability. The study focuses on the Australian banking sector within its unique regulatory and market context. The originality of this research lies in its localized empirical approach, providing context-specific evidence of blockchain’s strategic contribution to financial performance in banking.</jats:p>', '10.3389/fbloc.2025.1463633', 'https://doi.org/10.3389/fbloc.2025.1463633' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.3389/fbloc.2025.1463633');
