INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Blockchain consorcial aplicación de la tecnología Blockchain en la propiedad horizontal', 'Ricardo Miguel Nicolás', 2021, '<jats:p>El presente trabajo, persigue como objetivo principal analizar si un proceso de digitalización de la vida consorcial y del derecho real de la propiedad horizontal, es legamente posible, en donde la aplicación de la tecnología blockchain como mecanismo regularizador, honesto, de confianza y superior al actual, nos permita controlar y validar las cuentas que lleva a diario el administrador, participar en la liquidación de expensas, conocer los libros consorciales, celebrar asambleas virtuales.</jats:p>', '10.22529/rbia.2021(2)06', 'https://doi.org/10.22529/rbia.2021(2)06' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.22529/rbia.2021(2)06');
