INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'A Peer-To-Peer Publication Model on Blockchain', 'Imtiaz Khan; Ali Shahaab', 2021, '<jats:p>In the past few decades, there has been a sharp rise of research irreproducibility and retraction, to a point that now is deemed as a crisis. Addressing this crisis, we present a peer-to-peer (P2P) publication model that utilizes blockchain and smart contract technologies. Focusing primarily on researchers and reviewers, the conceptual P2P publication model addresses the sociocultural and incentivization aspects of the irreproducibility crisis. In the P2P publication model, instead of a complete publication, a preapproved experimental design will be published on an incremental basis (unit-by-unit) and authorship will be shared with reviewers. The concept of the P2P publication model was inspired by the transformational journey the music publishing industry has undertaken as it traverses through vinyl age (complete albums) to the Spotify age (single-by-single), where there is a growing inclination among artists toward building an incremental album, taking account of feedback from fans and utilizing automated revenue collection and sharing systems. The ability to publish incrementally through the P2P publication model will relieve researchers from the burden of publishing complete and “good results” while simultaneously incentivizing reviewers to undertake rigorous review work to gain authorship credit in the research. The proposed P2P publication model aims to transform the century-old publication model and incentivization structure in alignment with open access publication ethos of the 21st century.</jats:p>', '10.3389/fbloc.2021.615726', 'https://doi.org/10.3389/fbloc.2021.615726' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.3389/fbloc.2021.615726');
