INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'If blockchain is the solution, robot security is the problem', 'Eduardo Castelló Ferrer', 2023, '<jats:p>Robotics systems of all types are revolutionizing a wide variety of industries—transportation, manufacturing, and even healthcare—and yet, many essential ingredients for robotics systems in the real world are not technologically ready for deployment. Currently, robots lack the protocols and standards required to be safe and secure outside factories. In an attempt to close this gap, recent research has demonstrated the security benefits of combining robotics systems with blockchain-based and related technologies (e.g., smart contracts, zero-knowledge proofs, Merkle trees). In this perspective article, I argue that blockchain-based robotics is starting to provide innovative solutions (e.g., secure data sharing, consensus mechanisms, and new interaction methods) to urgent problems of robot security. I list the most important takeaways so far from this emerging field of research that I helped establish together with a growing community. I close the article by discussing the implications of the security challenges that the robotics research community is facing, and possible ways for us to move forward.</jats:p>', '10.3389/fbloc.2023.1181820', 'https://doi.org/10.3389/fbloc.2023.1181820' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.3389/fbloc.2023.1181820');
