INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Improved blockchain-based ECDSA batch verification scheme', 'Guangfu Wu; Jiandong Zhou; Xiaoyan Fu', 2025, '<jats:sec><jats:title>Introduction</jats:title><jats:p>Blockchain technology has attracted much attention due to its decentralization, transparency and security. Initially applied in the financial field, it has now expanded to various fields such as Internet of Things (IoT), electronic cash and healthcare. However, the open nature of blockchain has raised potential security concerns about sensitive transaction data, and the increasing number of transactions requires low-latency solutions. Most blockchain applications still rely on the lightweight Elliptic Curve Digital Signature Algorithm (ECDSA). Due to complex operations such as vectorized multiplication and modular inversion, this may introduce significant additional overhead.</jats:p></jats:sec><jats:sec><jats:title>Methods</jats:title><jats:p>To address these issues, a new scheme named KTP-ECDSA is proposed. This scheme is based on the improved two-parameter Elliptic Curve Digital Signature Algorithm (TP-ECDSA) and the KGLP algorithm. In both the signing and verification processes, this scheme eliminates modular inverse operations and reduces scalar multiplications during the verification stage by using batch verification.</jats:p></jats:sec><jats:sec><jats:title>Result</jats:title><jats:p>The experimental results show that, compared with the traditional ECDSA, KTP-ECDSA has achieved a speed increase of over 50% in both independent verification and batch verification, significantly improving the efficiency of signature verification.</jats:p></jats:sec><jats:sec><jats:title>Discussion</jats:title><jats:p>By adopting the KTP-ECDSA algorithm and using the digital signature batch verification method, multiple signatures can be verified simultaneously, thus reducing the computational burden of the traditional single-verification method. This greatly increases the overall transaction throughput and improves resource utilization efficiency.</jats:p></jats:sec>', '10.3389/fbloc.2025.1495984', 'https://doi.org/10.3389/fbloc.2025.1495984' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.3389/fbloc.2025.1495984');
