INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'CoINS‐Parking: Compressed IoT Blockchain Network Smart Parking', 'Danial Fazelpour; Athena Abdi', 2025, '<jats:title>ABSTRACT</jats:title>                   <jats:p>In this paper, CoINS‐Parking, a compressed IoT blockchain network for smart parking systems, is presented. Smart parking collects data and processes it to provide real‐time information about parking availability. This data includes the environmental information through the sensors and the users'' information, which mainly has a confidentiality requirement. In CoINS‐Parking, this data is transmitted to the blockchain network using a hybrid mesh‐star topology. Data integrity, confidentiality, and memory management are the main requirements of this data‐driven system that are provided through hashing, encryption, and data compression. Moreover, the response time of CoINS‐Parking is improved by optimizing the mentioned schemes and modifying the conventional hash structure. This scheme finds the previous chain of the network in a short time, employing the largest prime factor in tree construction. To evaluate the efficiency of the proposed method, various experiments are considered, and it is compared to related studies. Based on these experiments, CoINS‐Parking outperforms related methods in terms of memory and gas usage by about 4.4% and improves their security dramatically in cost of about 11% increase in execution time.</jats:p>', '10.1049/blc2.70027', 'https://doi.org/10.1049/blc2.70027' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1049/blc2.70027');
