INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Design and implementation of an edge computing-based GPS tracking system', 'Mykola V. Klymenko; Andrii M. Striuk', 2023, '<jats:p> This paper presents a comprehensive study on the technical aspects of edge-enabled GPS tracking systems, their evolution, and an analysis of existing problem-solving approaches. It introduces mathematical models that simulate the operation of the hardware and software components of these systems. An adaptive user interface has been developed, enabling usage across various platforms such as smartphones and personal computers. The paper also explores innovative methods for visualizing the trajectory of a moving object on an electronic map. Specialized software for the Atmega162-16PU microcontroller has been developed to control the GSM module and GPS receiver. A novel method for data transmission from a GPS tracker to a web server is proposed. The paper concludes with the successful testing of two experimental GPS-tracker prototypes under uncertain conditions. The developed edge-enabled GPS tracking software and hardware show potential for monitoring moving objects within the coverage of GSM cellular networks.</jats:p>', '10.55056/jec.634', 'https://doi.org/10.55056/jec.634' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.55056/jec.634');
