INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Introduction to doors Workshops on Edge Computing (2021-2023)', 'Tetiana A. Vakaliuk; Serhiy O. Semerikov', 2023, '<jats:p>The Edge Computing Workshop, known as "doors", has evolved as a prominent international forum for researchers, practitioners, and industry experts to converge and discuss the latest advancements and applications in the field of edge computing. This paper provides an overview of the doors workshops held from 2021 to 2023, highlighting their objectives, topics of interest, committees, and the significant contributions made by researchers during these years. The workshops have played a pivotal role in fostering collaboration, sharing insights, and exploring emerging trends in edge computing, addressing challenges related to infrastructure, systems, security, applications, and more. This paper underscores the importance of these workshops in advancing the field and promoting innovation in the era of digital transformation.</jats:p>', '10.55056/jec.618', 'https://doi.org/10.55056/jec.618' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.55056/jec.618');
