INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Edge computing research: a bibliometric analysis and JEC Volume 3 Issue 2 (2024) highlights', 'Tetiana A. Vakaliuk', 2024, '<jats:p>This editorial presents a bibliometric analysis of edge computing research published in IEEE Access from 2018 to 2023, followed by an overview and discussion of the papers featured in the current issue of the Journal of Edge Computing (JEC), Volume 3, Issue 2 (2024). The IEEE Access analysis reveals key trends and themes in edge computing research, including IoT integration, AI and machine learning applications, resource management, wireless networks, and security concerns. The most cited authors, countries, and collaboration patterns are also identified. The JEC papers align well with these findings, addressing challenges and proposing novel solutions in areas such as IoT interoperability, plant disease detection using deep learning, wireless technologies in IoT projects, efficient operating systems, and adaptive IoT honeypot frameworks. The research in both IEEE Access and JEC demonstrates the rapid advancements and growing importance of edge computing in various domains.</jats:p>', '10.55056/jec.853', 'https://doi.org/10.55056/jec.853' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.55056/jec.853');
