INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Analysis and protection of IoT systems: Edge computing and decentralized decision-making', 'Nadiia M. Lobanchykova; Ihor A. Pilkevych; Oleksandr Korchenko', 2022, '<jats:p>This article presents a detailed analysis of the Internet of Things (IoT) systems and the methods used to protect them. The article highlights the potential of edge computing to minimize traffic transmission and the decentralization of decision-making systems to enhance security. The analysis examines attacks on IoT system components and provides protection recommendations. Furthermore, the article explores the prospects of information protection in IoT systems.</jats:p>', '10.55056/jec.573', 'https://doi.org/10.55056/jec.573' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.55056/jec.573');
