INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Edge of the Network: Charting the Evolution of Edge Computing', 'M. Bhuvaneswari; Syeda Hifsa Naaz', 2024, '<jats:p>The following paper offers an in-depth examination of the burgeoning field of (EC)edge computing, which revolutionizes conventional cloud-centric paradigms by moving computation closer to the data source. This survey navigates through the fundamental concepts, architectures, applications, challenges, and future directions of edge computing. By elucidating various architectural models, including fog computing and mobile edge computing, it explores the diverse array of industries benefiting from edge computing, such as IoT, healthcare, and smart cities. Additionally, the survey identifies key challenges, including security, privacy, and resource management, while presenting promising avenues for innovation. Ultimately, this survey serves as a roadmap for researchers, practitioners, and enthusiasts alike, guiding them through the dynamic landscape of edge computing.</jats:p>', '10.48001/jodsc.2024.1118-32', 'https://doi.org/10.48001/jodsc.2024.1118-32' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.48001/jodsc.2024.1118-32');
