INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'EDGE COMPUTING VA EDGE INTELLIGENCE: IOT TIZIMLARIDA SAMARADORLIK VA TEZKOR QAROR QABUL QILISH IMKONIYATLARI', 'Gulora Razzakova', 2025, '<jats:p>Mazkur maqolada Internet of Things (IoT) tizimlarida Edge Computing va Edge Intelligence texnologiyalarining roli, ahamiyati va qo‘llanilish imkoniyatlari keng yoritilgan. An’anaviy bulutli hisoblash arxitekturasining cheklovlarini yengib o‘tish uchun chekka (edge) darajada ma’lumotni qayta ishlash va sun’iy intellektni integratsiyalash muhim yechim sifatida taqdim etiladi. Edge Intelligence konsepsiyasi orqali IoT qurilmalarining real vaqtda ishlashi, tarmoq kechikishini kamaytirish, xavfsizlikni kuchaytirish, va avtonom qaror qabul qilish kabi imkoniyatlar ko‘rib chiqiladi. Maqolada shuningdek, ushbu texnologiyalarning kuzatuv kameralaridan tortib dronlar, aqlli uylar, qishloq xo‘jaligi va chakana savdo kabi sohalardagi amaliy qo‘llanishi misollar asosida tahlil qilingan. Tadqiqot shuningdek, mavjud muammolar, texnik to‘siqlar va TinyML, 5G texnologiyalari bilan bog‘liq rivojlanish istiqbollarini ham qamrab oladi.</jats:p>', '10.47390/ts3030-3702v3i2y2025n02', 'https://doi.org/10.47390/ts3030-3702v3i2y2025n02' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.47390/ts3030-3702v3i2y2025n02');
