INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Edge computing in environmental science: automated intelligent robotic platform for water quality assessment', 'Andrii G. Tkachuk; Mariia S. Hrynevych; Tetiana A. Vakaliuk; Oksana A. Chernysh; Mykhailo G. Medvediev', 2023, '<jats:p>This paper introduces a novel intelligent robotic platform designed to expedite and enhance the process of water quality assessment and bottom relief analysis in reservoirs. The platform, equipped with an array of sensors and actuators, is capable of conducting comprehensive studies over larger areas of the reservoir, thereby overcoming the limitations of traditional water analysis methods. The platform’s advanced design includes a control board, servo motors, a brushless motor, a radio module, a GPS module, and a motor speed controller, all housed within a robust casing. The paper presents a functional diagram of the platform and discusses the results of a system study conducted on a reservoir. The study aimed to verify the system’s operation, evaluate the effectiveness of the research conducted, and calibrate water quality sensors. The platform utilizes an ultrasonic sensor for depth measurement and sensors for water acidity and temperature. The results of the monitoring system experiments led to the creation of a detailed map of the reservoir’s bottom area and provided valuable insights into water quality.</jats:p>', '10.55056/jec.633', 'https://doi.org/10.55056/jec.633' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.55056/jec.633');
