INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Edge Computing und digitaler Schatten*/Edge computing and digital shadow', 'C. Brecher; M. Obdenbusch; M. Buchsbaum; T. Buchner; J. Waltl', 2018, '<p>Produktionssysteme müssen eine hohe Flexibilität und Anpassungsfähigkeit aufweisen, um zukünftige Anforderungen zu erfüllen, zum Beispiel hinsichtlich resilienter Prozesse. Durch neue Informations- und Kommunikationstechnologien ergeben sich Potenziale für die Einführung eines lebenszyklusübergreifenden Datenmanagements. Mit dem Edge Computing als Enabler wird ein Konzept zur Einführung und Nutzung des digitalen Schattens vorgestellt und anhand eines industriellen Anwendungsfalls implementiert und diskutiert.</p>           <p>&amp;nbsp;</p>           <p>Production systems must provide a high degree of flexibility and adaptability in order to meet future requirements, e. g. with regard to resilient processes. New ICT technologies open up opportunities for introducing an overall life cycle data management. With edge computing as an enabling technology, a method for introducing and using digital shadows is presented, implemented and discussed on the basis of an industrial use case.</p>', '10.37544/1436-4980-2018-05-39', 'https://doi.org/10.37544/1436-4980-2018-05-39' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.37544/1436-4980-2018-05-39');
