INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Gene Expression Programming for Quantum Computing', 'Gonzalo Alvarez; Ryan Bennink; Stephan Irle; Jacek Jakowski', 2023, '<jats:p>             We introduce             <jats:sc>QuantumGEP</jats:sc>             , a scientific computer program that uses gene expression programming (GEP) to find a quantum circuit that either (1) maps a given set of input states to a given set of output states or (2) transforms a fixed initial state to minimize a given physical quantity of the output state.             <jats:sc>QuantumGEP</jats:sc>             is a driver program that uses             <jats:sc>evendim</jats:sc>             , a generic computational engine for GEP, both of which are free and open source. We apply             <jats:sc>QuantumGEP</jats:sc>             as a powerful solver for MaxCut in graphs and for condensed matter quantum many-body Hamiltonians.           </jats:p>', '10.1145/3617691', 'https://doi.org/10.1145/3617691' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3617691');
