INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Extending Python for Quantum-classical Computing via Quantum Just-in-time Compilation', 'Thien Nguyen; Alexander J. McCaskey', 2022, '<jats:p>Python is a popular programming language known for its flexibility, usability, readability, and focus on developer productivity. The quantum software community has adopted Python on a number of large-scale efforts due to these characteristics, as well as the remote nature of near-term quantum processors. The use of Python has enabled quick prototyping for quantum code that directly benefits pertinent research and development efforts in quantum scientific computing. However, this rapid prototyping ability comes at the cost of future performant integration for tightly coupled CPU-QPU architectures with fast-feedback. Here, we present a language extension to Python that enables heterogeneous quantum-classical computing via a robust C++ infrastructure for quantum just-in-time (QJIT) compilation. Our work builds off the QCOR C++ language extension and compiler infrastructure to enable a single-source, quantum hardware-agnostic approach to quantum-classical computing that retains the performance required for tightly coupled CPU-QPU compute models. We detail this Python extension, its programming model and underlying software architecture, and provide a robust set of examples to demonstrate the utility of our approach.</jats:p>', '10.1145/3544496', 'https://doi.org/10.1145/3544496' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3544496');
INSERT INTO tags (name) SELECT 'Quantum Computing' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Quantum Computing');
INSERT INTO publications_tags (publication_id, tag_id) SELECT p.id, t.id FROM publications p JOIN tags t ON t.name = 'Quantum Computing' WHERE p.doi = '10.1145/3544496' AND NOT EXISTS (SELECT 1 FROM publications_tags pt WHERE pt.publication_id = p.id AND pt.tag_id = t.id);
INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Quantum randomized encoding, verification of quantum computing, no-cloning, and blind quantum computing', 'Tomoyuki Morimae', 2021, '<jats:p>Randomized encoding is a powerful cryptographic primitive with various applications such as secure multiparty computation, verifiable computation, parallel cryptography, and complexity lower bounds. Intuitively, randomized encoding $\\hat{f}$ of a function $f$ is another function such that $f(x)$ can be recovered from $\\hat{f}(x)$, and nothing except for $f(x)$ is leaked from $\\hat{f}(x)$. Its quantum version, quantum randomized encoding, has been introduced recently [Brakerski and Yuen, arXiv:2006.01085]. Intuitively, quantum randomized encoding $\\hat{F}$ of a quantum operation $F$ is another quantum operation such that, for any quantum state $\\rho$, $F(\\rho)$ can be recovered from $\\hat{F}(\\rho)$, and nothing except for $F(\\rho)$ is leaked from $\\hat{F}(\\rho)$. In this paper, we show three results. First, we show that if quantum randomized encoding of BB84 state generations is possible with an encoding operation $E$, then a two-round verification of quantum computing is possible with a classical verifier who can additionally do the operation $E$. One of the most important goals in the field of the verification of quantum computing is to construct a verification protocol with a verifier as classical as possible. This result therefore demonstrates a potential application of quantum randomized encoding to the verification of quantum computing: if we can find a good quantum randomized encoding (in terms of the encoding complexity), then we can construct a good verification protocol of quantum computing. Our second result is, however, to show that too good quantum randomized encoding is impossible: if quantum randomized encoding for the generation of even simple states (such as BB84 states) is possible with a classical encoding operation, then the no-cloning is violated. Finally, we consider a natural modification of blind quantum computing protocols in such a way that the server gets the output like quantum randomized encoding. We show that the modified protocol is not secure.</jats:p>', '10.26421/qic21.13-14-3', 'https://doi.org/10.26421/qic21.13-14-3' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.26421/qic21.13-14-3');
