INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'QFOR: A Fidelity-aware Orchestrator for Quantum Computing Environments using Deep Reinforcement Learning', 'Hoa Nguyen; Muhammad Usman; Rajkumar Buyya', 2026, '<jats:p>                     Quantum cloud computing enables remote access to quantum processors, yet the heterogeneity and noise of available quantum hardware create significant challenges for efficient resource orchestration. These issues complicate the optimisation of quantum task allocation and scheduling, as existing heuristic methods fall short in adapting to dynamic conditions or effectively balancing execution fidelity and time. Here, we propose QFOR, a                     <jats:bold>Q</jats:bold>                     uantum                     <jats:bold>F</jats:bold>                     idelity-aware                     <jats:bold>O</jats:bold>                     rchestration of tasks across heterogeneous quantum nodes in cloud-based environments using Deep                     <jats:bold>R</jats:bold>                     einforcement learning. We model the quantum task orchestration as a Markov Decision Process and employ the Proximal Policy Optimisation algorithm to learn adaptive scheduling policies, using IBM quantum processor calibration data for noise-aware performance estimation. Our configurable framework balances overall quantum task execution fidelity and time, enabling adaptation to different operational priorities. Extensive evaluation demonstrates that QFOR is adaptive and achieves significant performance with 29.5-84% improvements in relative fidelity performance over other deep reinforcement learning and heuristic baselines. Furthermore, it maintains comparable quantum execution times, contributing to cost-efficient use of quantum computation resources.                   </jats:p>', '10.1145/3799898', 'https://doi.org/10.1145/3799898' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3799898');
