INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Improved Routing of Multiparty Entanglement over Quantum Networks', 'Nirupam Basak; Goutam Paul', 2026, '<jats:p>The effective routing of entanglement over a quantum network is a fundamental problem in quantum communication. The distribution and reshaping of multipartite entanglement over a quantum network requires scalable protocols that adapt to the underlying topology. Graph states provide a convenient framework for this challenging task, as they encode global entanglement in a structured way that can be locally manipulated to produce a variety of target states, without requiring additional long-distance quantum operations. In this paper, we propose graph-state-based routing protocols for sharing GHZ states, achieving larger sizes than those achieved in the existing works for given network topologies. For this improvement, we consider tree structures connecting the users participating in the final GHZ states, as opposed to the linear configurations used in the earlier works. In particular, for grid networks, we show special constructions of such trees that achieve larger GHZ states than the prior works. Moreover, if the user nodes along which the entanglement is to be routed are pre-specified, a strategy is proposed to accomplish this routing.</jats:p>', '10.1145/3811537', 'https://doi.org/10.1145/3811537' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3811537');
