INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Near-Heisenberg-limit Quantum Computing', 'Frank Zhigang Wang', 2026, '<jats:p>                     Quantum computing is fundamentally limited by the Planck constant (                     <jats:inline-formula content-type="math/tex">                       <jats:tex-math notation="LaTeX" version="MathJax">\\(h = 6.63\\ \\times {{10}^{ - 34}}\\ J \\cdot s\\)</jats:tex-math>                     </jats:inline-formula>                     ) through the Heisenberg Limit. The energy consumption over a given time, or the speed of processing information with a specific energy budget, is a core research focus in quantum computing. To date, the smallest action (the energy-time cost) achieved is approximately                     <jats:inline-formula content-type="math/tex">                       <jats:tex-math notation="LaTeX" version="MathJax">\\({{10}^{ - 29}}J \\cdot s\\)</jats:tex-math>                     </jats:inline-formula>                     , using a giant spin qubit composed of 20 spins. In our study, we achieved an action of                     <jats:inline-formula content-type="math/tex">                       <jats:tex-math notation="LaTeX" version="MathJax">\\(1.66\\ \\times {{10}^{ - 34}}\\ J \\cdot s\\)</jats:tex-math>                     </jats:inline-formula>                     to reversibly manipulate a single spin qubit through a spin-spin magnetic interaction experiment. By adhering to the principle of least action, our theoretical and experimental results establish the minimal action required. Our findings highlight the potential of spin-qubit quantum computers as accelerators for computation-intensive applications, such as AI and Post-Quantum Cryptography, since they exhibit several unique advantages: 1. High energy efficiency (by approaching the Heisenberg limit as well as the Landauer bound); 2. High-density integration (with just an atom/ion per qubit); 3. Long coherence times (tens of seconds); 4. High-fidelity (98%); and 5. Fault tolerance (through decoherence-free subspaces).                   </jats:p>', '10.1145/3769850', 'https://doi.org/10.1145/3769850' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3769850');
