INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Quantum Computing in the NISQ era and beyond', 'John Preskill', 2018, '<jats:p>Noisy Intermediate-Scale Quantum (NISQ) technology will be available in the near future. Quantum computers with 50-100 qubits may be able to perform tasks which surpass the capabilities of today''s classical digital computers, but noise in quantum gates will limit the size of quantum circuits that can be executed reliably. NISQ devices will be useful tools for exploring many-body quantum physics, and may have other useful applications, but the 100-qubit quantum computer will not change the world right away - we should regard it as a significant step toward the more powerful quantum technologies of the future. Quantum technologists should continue to strive for more accurate quantum gates and, eventually, fully fault-tolerant quantum computing.</jats:p>', '10.22331/q-2018-08-06-79', 'https://doi.org/10.22331/q-2018-08-06-79' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.22331/q-2018-08-06-79');
