INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Comparison of Quantum Computing Versus Traditional Computing and Use of Python in Implementation of Quantum Computing', 'Manojkumar Langote; Gorakshanath T.Gund; Sandeep Sonawane', 2022, '', '10.2139/ssrn.4091405', 'https://doi.org/10.2139/ssrn.4091405' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.2139/ssrn.4091405');
