INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Quantum Machine Learning Algorithm for Knowledge Graphs', 'Yunpu Ma; Volker Tresp', 2021, '<jats:p>Semantic knowledge graphs are large-scale triple-oriented databases for knowledge representation and reasoning. Implicit knowledge can be inferred by modeling the tensor representations generated from knowledge graphs. However, as the sizes of knowledge graphs continue to grow, classical modeling becomes increasingly computationally resource intensive. This article investigates how to capitalize on quantum resources to accelerate the modeling of knowledge graphs. In particular, we propose the first quantum machine learning algorithm for inference on tensorized data, i.e., on knowledge graphs. Since most tensor problems are NP-hard [18], it is challenging to devise quantum algorithms to support the inference task. We simplify the modeling task by making the plausible assumption that the tensor representation of a knowledge graph can be approximated by its low-rank tensor singular value decomposition, which is verified by our experiments. The proposed sampling-based quantum algorithm achieves speedup with a polylogarithmic runtime in the dimension of knowledge graph tensor.</jats:p>', '10.1145/3467982', 'https://doi.org/10.1145/3467982' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3467982');
