INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Visualizing Quantum Circuits: State Vector Difference Highlighting and the Half-Matrix', 'Michael McGuffin; Jean-Marc Robert', 2026, '<jats:p>Existing graphical user interfaces for circuit simulators often show small visual summaries of the reduced state of each qubit, showing the probability, phase, purity, and/or Bloch sphere coordinates associated with each qubit. These necessarily provide an incomplete picture of the quantum state of the qubits, and can sometimes be confusing for students or newcomers to quantum computing. We contribute two novel visual approaches to provide more complete information about small circuits. First, to complement information about each qubit, we show the complete state vector, and illustrate the way that amplitudes change from layer-to-layer under the effect of different gates, by using a small set of colors, arrows, and symbols. We call this “state vector difference highlighting”, and show how it elucidates the effect of Hadamard, X, Y, Z, S, T, Phase, and SWAP gates, where each gate may have an arbitrary combination of control and anticontrol qubits. Second, we display pairwise information about qubits (such as concurrence and correlation) in a triangular “half-matrix” visualization. Our open source software implementation, called MuqcsCraft, is available as a live online demonstration that runs in a web browser without installing any additional software, allowing a user to define a circuit through drag-and-drop actions, and then simulate and visualize it.</jats:p>', '10.1145/3786463', 'https://doi.org/10.1145/3786463' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3786463');
