INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Undecidable, Unrecognizable, and Quantum Computing', 'Michael Siomau', 2020, '<jats:p>Quantum computing allows us to solve some problems much faster than existing classical algorithms. Yet, the quantum computer has been believed to be no more powerful than the most general computing model—the Turing machine. Undecidable problems, such as the halting problem, and unrecognizable inputs, such as the real numbers, are beyond the theoretical limit of the Turing machine. I suggest a model for a quantum computer, which is less general than the Turing machine, but may solve the halting problem for any task programmable on it. Moreover, inputs unrecognizable by the Turing machine can be recognized by the model, thus breaking the theoretical limit for a computational task. A quantum computer is not just a successful design of the Turing machine as it is widely perceived now, but is a different, less general but more powerful model for computing, the practical realization of which may need different strategies than those in use now.</jats:p>', '10.3390/quantum2030023', 'https://doi.org/10.3390/quantum2030023' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.3390/quantum2030023');
INSERT INTO tags (name) SELECT 'Quantum Computing' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Quantum Computing');
