INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Quantum Computing Arrives', '', 2023, '<jats:p>Quantum computing arrives. Our previous work shows at least 4 quantum properties that are indeed universal in some number systems; here we use them to enable quantum computing. Using the sets N, Z, Q, and Q*, one has +4 quantum properties that one can trust, as archetypes of easy communication to friends and foes, to ignoranti or cognoscenti, and for quantum consciousness. Therefore, this work applies to computer calculations, apps in cell phones, algebra, and in the human mind</jats:p>', '10.33140/jmtcm.02.08.02', 'https://doi.org/10.33140/jmtcm.02.08.02' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.33140/jmtcm.02.08.02');
