INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Quantum computers, quantum computing, and quantum thermodynamics', 'Fabrizio Cleri', 2024, '<jats:p>Quantum thermodynamics aims to extend standard thermodynamics and non-equilibrium statistical physics to systems with sizes well below the thermodynamic limit. It is a rapidly evolving research field that promises to change our understanding of the foundations of physics, while enabling the discovery of novel thermodynamic techniques and applications at the nanoscale. Thermal management has turned into a major obstacle in pushing the limits of conventional digital computers and could also represent a crucial issue for quantum computers. The practical realization of quantum computers with superconducting loops requires working at cryogenic temperatures to eliminate thermal noise, and ion-trap qubits also need low temperatures to minimize collisional noise. In both cases, the sub-nanometric sizes also bring about the thermal broadening of the quantum states; and even room-temperature photonic computers eventually require cryogenic detectors. A number of thermal and thermodynamic questions, therefore, take center stage, such as quantum re-definitions of work and heat, thermalization and randomization of quantum states, the overlap of quantum and thermal fluctuations, and many others, even including a proper definition of temperature for the small open systems constantly out of equilibrium that are the qubits. This overview provides an introductory perspective on a selection of current trends in quantum thermodynamics and their impact on quantum computers and quantum computing, with language that is accessible to postgraduate students and researchers from different fields.</jats:p>', '10.3389/frqst.2024.1422257', 'https://doi.org/10.3389/frqst.2024.1422257' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.3389/frqst.2024.1422257');
