INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Leveraging State Sparsity for More Efficient Quantum Simulations', 'Samuel Jaques; Thomas Häner', 2022, '<jats:p>High-performance techniques to simulate quantum programs on classical hardware rely on exponentially large vectors to represent quantum states. When simulating quantum algorithms, the quantum states that occur are often sparse due to special structure in the algorithm or even in the underlying problem. We thus introduce a new simulation method that exploits this sparsity to reduce memory usage and simulation runtime. Moreover, our prototype implementation includes optimizations such as gate (re)scheduling, which amortizes data structure accesses and reduces memory usage. To benchmark our implementation, we run quantum algorithms for factoring, for computing integer and elliptic curve discrete logarithms, and for chemistry. Our simulator successfully runs a factoring instance of a 20-bit number using 102 qubits, and elliptic curve discrete logarithm over a 10-bit curve with 110 qubits. While previous work needed a supercomputer to simulate such instances of factoring, our approach succeeds in less than four minutes using a single core and less than 100 MB of memory. To the best of our knowledge, we are the first to fully simulate a quantum algorithm to compute elliptic curve discrete logarithms.</jats:p>', '10.1145/3491248', 'https://doi.org/10.1145/3491248' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3491248');
INSERT INTO tags (name) SELECT 'Quantum Computing' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Quantum Computing');
INSERT INTO publications_tags (publication_id, tag_id) SELECT p.id, t.id FROM publications p JOIN tags t ON t.name = 'Quantum Computing' WHERE p.doi = '10.1145/3491248' AND NOT EXISTS (SELECT 1 FROM publications_tags pt WHERE pt.publication_id = p.id AND pt.tag_id = t.id);
INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Quantum and Randomised Algorithms for Non-linearity Estimation', 'Debajyoti Bera; Sapv Tharrmashastha', 2021, '<jats:p>             Non-linearity of a Boolean function indicates how far it is from any linear function. Despite there being several strong results about identifying a linear function and distinguishing one from a sufficiently non-linear function, we found a surprising lack of work on computing the non-linearity of a function. The non-linearity is related to the Walsh coefficient with the largest absolute value; however, the naive attempt of picking the maximum after constructing a Walsh spectrum requires Θ (2             <jats:sup>n</jats:sup>             ) queries to an             <jats:italic>n</jats:italic>             -bit function. We improve the scenario by designing highly efficient quantum and randomised algorithms to approximate the non-linearity allowing additive error, denoted λ, with query complexities that depend polynomially on λ. We prove lower bounds to show that these are not very far from the optimal ones. The number of queries made by our randomised algorithm is linear in             <jats:italic>n</jats:italic>             , already an exponential improvement, and the number of queries made by our quantum algorithm is surprisingly independent of             <jats:italic>n</jats:italic>             . Our randomised algorithm uses a Goldreich-Levin style of navigating all Walsh coefficients and our quantum algorithm uses a clever combination of Deutsch-Jozsa, amplitude amplification and amplitude estimation to improve upon the existing quantum versions of the Goldreich-Levin technique.           </jats:p>', '10.1145/3456509', 'https://doi.org/10.1145/3456509' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3456509');
INSERT INTO tags (name) SELECT 'Quantum Computing' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Quantum Computing');
