INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Reinforcement Learning in der Produktionssteuerung/Reinforcement Learning for production control', 'Eckart Uhlmann; Julian Polte; Christopher Mühlich', 2025, '<p>Die Steuerung von Produktionsprozessen stellt aufgrund der hohen Prozesskomplexität eine zentrale Herausforderung für produzierende Unternehmen dar. Vor diesem Hintergrund gewinnt die Automatisierung von Planungs- und Steuerungsaufgaben durch Algorithmen zunehmend an Bedeutung. Methoden des Reinforcement Learning bieten vielversprechendes Potenzial, um diese Herausforderung zu adressieren. Dieser Beitrag vergleicht Methoden des Reinforcement Learning mit exakten und metaheuristischen Algorithmen, um die Einsatzgrenzen und die Konkurrenzfähigkeit lernbasierter Verfahren im aktuellen Entwicklungsstand zu bewerten.</p>', '10.37544/1436-4980-2025-11-12-90', 'https://doi.org/10.37544/1436-4980-2025-11-12-90' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.37544/1436-4980-2025-11-12-90');
