INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'DEEP REINFORCEMENT LEARNING ON STOCK DATA', '; Abdullayev Nurmuhammet', 2023, '<jats:p>This study proposes using Deep Reinforcement Learning (DRL) for stock trading decisions and prediction. DRL is a machine learning technique that enables agents to learn optimal strategies by interacting with their environment. The proposed model surpasses traditional models and can make informed trading decisions in real-time. The study highlights  the feasibility of applying DRL in financial markets and its advantages in strategic decision- making. The model''s ability to learn from market dynamics makes it a promising approach  for stock market forecasting. Overall, this paper provides valuable insights into the use of DRL for stock trading decisions and prediction, establishing a strong case for its adoption in financial markets. Keywords: reinforcement learning, stock market, deep reinforcement learning.</jats:p>', '10.17015/aas.2023.232.49', 'https://doi.org/10.17015/aas.2023.232.49' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.17015/aas.2023.232.49');
