INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Comparison of Multiple Reinforcement Learning and Deep Reinforcement Learning Methods for the Task Aimed at Achieving the Goal', 'Roman Parak; Radomil Matousek', 2021, '<jats:p>Reinforcement Learning (RL) and Deep Reinforcement Learning (DRL) methods are a promising approach to solving complex tasks in the real world with physical robots. In this paper, we compare several reinforcement  learning (Q-Learning, SARSA) and deep reinforcement learning (Deep Q-Network, Deep Sarsa) methods for a task aimed at achieving a specific goal using robotics arm UR3. The main optimization problem of this experiment is to find the best solution for each RL/DRL scenario and minimize the Euclidean distance accuracy error and smooth the resulting path by the Bézier spline method. The simulation and real word applications are controlled by the Robot Operating System (ROS). The learning environment is implemented using the OpenAI Gym library which uses the RVIZ simulation tool and the Gazebo 3D modeling tool for dynamics and kinematics.</jats:p>', '10.13164/mendel.2021.1.001', 'https://doi.org/10.13164/mendel.2021.1.001' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.13164/mendel.2021.1.001');
