INSERT INTO publications_tags (publication_id, tag_id) SELECT p.id, t.id FROM publications p JOIN tags t ON t.name = 'Reinforcement Learning' WHERE p.doi = '10.3390/electronics12234752' AND NOT EXISTS (SELECT 1 FROM publications_tags pt WHERE pt.publication_id = p.id AND pt.tag_id = t.id);
INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Reinforcement learning for UAV flight controls: Evaluating continuous space reinforcement learning algorithms for fixed-wing UAVs', 'Hasan Raza Khanzada; Adnan Maqsood; Abdul Basit', 2025, '<jats:p>Flight controls are experiencing a major shift with the integration of reinforcement learning (RL). Recent studies have demonstrated the potential of RL to deliver robust and precise control across diverse applications, including the flight control of fixed-wing unmanned aerial vehicles (UAVs). However, a critical gap persists in the rigorous evaluation and comparative analysis of leading continuous-space RL algorithms. This paper aims to provide a comparative analysis of RL-driven flight control systems for fixed-wing UAVs in dynamic and uncertain environments. Five prominent RL algorithms that include Deep Deterministic Policy Gradient (DDPG), Twin Delayed Deep Deterministic Policy Gradient (TD3), Proximal Policy Optimization (PPO), Trust Region Policy Optimization (TRPO) and Soft Actor-Critic (SAC) are evaluated to determine their suitability for complex UAV flight dynamics, while highlighting their relative strengths and limitations. All the RL agents are trained in a same high fidelity simulation environment to control pitch, roll and heading of the UAV under varying flight conditions. The results demonstrate that RL algorithms outperformed the classical PID controllers in terms of stability, responsiveness and robustness, especially during environmental disturbances such as wind gusts. The comparative analysis reveals that the SAC algorithm achieves convergence in 400 episodes and maintains a steady-state error below 3%, offering the best trade-off among the evaluated RL algorithms. This analysis aims to provide valuable insight for the selection of suitable RL algorithm and their practical integration into modern UAV control systems.</jats:p>', '10.1371/journal.pone.0334219', 'https://doi.org/10.1371/journal.pone.0334219' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1371/journal.pone.0334219');
