INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Tinjauan Supervised Reinforcement Learning pada  Tindakan Medis Penyakit Diabetes Melitus', 'Indah Pratiwi Putri; Dona Marcelina; Evi Yulianti', 2024, '<jats:p>Diabetes Melitus (DM) merupakan penyakit kronis yang memerlukan pengelolaan medis yang berkelanjutan. Pengelolaan pengendalian penyakit diabetes bergantung pada kadar glukosa  dalam darah guna mengambil tindakan yang tepat agar dapat mencegah kadar glukosa darah menjadi terlalu rendah atau tinggi. Dalam konteks perawatan medis DM, penggunaan teknologi pembelajaran mesin, khususnya Supervised Reinforcement Learning (SRL) telah mengahadirkan pendekatan yang inovatif. Penelitian ini bertujuan untuk menyelidiki dan merangkum beberapa karya ilmiah yang membahas tentang penerapan SRL dalam konteks tindakan medis untuk penyakit DM. Beberapa percobaan dilakukan oleh para peneliti dengan menggunakan data dari pasien diabetes untuk menentukan parameter model yang optimal, melakukan simulasi dan studi validasi secara real-time sehinga dapat memberikan wawasan lebih lanjut tentang penerapan praktis model pembelajaran penguatan dalam pengaturan klinis. Melalui SRL, agen pembelajaran dapat menggabungkan umpan balik lingkungan dengan informasi eksplisit dari supervisor untuk menghasilkan keputusan yang optimal dalam pengelolaan DM. Dalam makalah ini, penulis menganalisis kajian literatur terkait penerapan SRL pada pengelolaan medis DM, serta mengeksplorasi potensi dan tantangan yang terkait dengan penggunaan pendekatan ini dalam praktik klinis</jats:p>', '10.57152/malcom.v4i3.1363', 'https://doi.org/10.57152/malcom.v4i3.1363' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.57152/malcom.v4i3.1363');
