INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Can Big Data Machines Analyze Stock Market Sentiment?', 'Vasant Dhar', 2014, '<jats:title>Abstract</jats:title>                   <jats:p>Do the massive amounts of social and professionally curated data on the Internet contain useful sentiment about the market that “big data machines” can extract systematically? If so, what are the important challenges in creating economic value from these diffuse sources? In this commentary, I delve into these questions and frame the challenges involved using recent market developments as an illustrative backdrop.</jats:p>', '10.1089/big.2014.1528', 'https://doi.org/10.1089/big.2014.1528' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1089/big.2014.1528');
