INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Big Data and Predictive Analytics in Health Care', 'Vasant Dhar', 2014, '<jats:title>Abstract</jats:title>                   <jats:p>Predictive analytics show great promise in health care but face some serious hurdles for widespread adoption. I discuss the state of the art of predictive health-care analytics using the clinical arena as an example and discuss how the outputs of predictive systems could be made actionable through differentiated processes that encourage prevention. Such systems have the potential to minimize health risk at the population and individual levels through more personalized health-care delivery.</jats:p>', '10.1089/big.2014.1525', 'https://doi.org/10.1089/big.2014.1525' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1089/big.2014.1525');
