INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Big Data ethics', 'Andrej Zwitter', 2014, '<jats:p>The speed of development in Big Data and associated phenomena, such as social media, has surpassed the capacity of the average consumer to understand his or her actions and their knock-on effects. We are moving towards changes in how ethics has to be perceived: away from individual decisions with specific and knowable outcomes, towards actions by many unaware that they may have taken actions with unintended consequences for anyone. Responses will require a rethinking of ethical choices, the lack thereof and how this will guide scientists, governments, and corporate agencies in handling Big Data. This essay elaborates on the ways Big Data impacts on ethical conceptions.</jats:p>', '10.1177/2053951714559253', 'https://doi.org/10.1177/2053951714559253' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1177/2053951714559253');
