INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Big Data and Social Good: Leveraging Data for Social Impact', 'Dr. Olivia Hughes', 2022, '<jats:p>The potential of big data to create social value and address societal challenges is enormous. By harnessing the power of big data, organizations can gain deep insights into various social issues, including poverty, education, healthcare, and environmental sustainability. This article explores how big data can be leveraged for social good, highlighting case studies and strategies that use data to improve public services, enhance social welfare, and promote social justice. The article also addresses the ethical considerations involved in using big data for social impact.</jats:p>', '10.71465/ajbd437', 'https://doi.org/10.71465/ajbd437' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.71465/ajbd437');
